/**
 * /utils/markdown.jsx
 * ---------------------------------------------------------------------------
 * Parser markdown ĐƠN GIẢN (tự viết, không dùng thư viện ngoài) -> React node.
 *
 * Hỗ trợ các cú pháp đang dùng trong README.md:
 *   - Heading  # .. ######
 *   - Code block  ```lang ... ```
 *   - Bảng  | a | b |  + dòng phân cách |---|---|
 *   - Danh sách  - item  /  1. item
 *   - Trích dẫn  > ...
 *   - Đường kẻ ngang  ---
 *   - Inline: **đậm**, `code`, [text](url)
 *
 * Component hiển thị dùng Ant Design (Typography, Table, Divider).
 * CSS nằm trong src/assets/styles.css (không dùng inline style).
 */

import React from 'react'
import { Typography, Table, Divider } from 'antd'

const { Title, Paragraph, Text, Link } = Typography

/* =========================================================================
 *  INLINE — **đậm**, `code`, [text](url)
 * ========================================================================= */

const INLINE_RE = /(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)]+\))/g

/**
 * Chuyển 1 dòng text -> mảng React node (đã xử lý cú pháp inline).
 * @param {string} text  nội dung 1 dòng
 * @param {string} prefix tiền tố key cho React
 */
export const parseInline = (text = '', prefix = 'i') => {
  const nodes = []
  let last = 0
  let index = 0
  let match

  INLINE_RE.lastIndex = 0
  while ((match = INLINE_RE.exec(text)) !== null) {
    if (match.index > last) nodes.push(text.slice(last, match.index))

    const token = match[0]
    const key = `${prefix}-${index++}`

    if (token.startsWith('**')) {
      nodes.push(
        <Text strong key={key}>
          {token.slice(2, -2)}
        </Text>,
      )
    } else if (token.startsWith('`')) {
      nodes.push(
        <Text code key={key}>
          {token.slice(1, -1)}
        </Text>,
      )
    } else {
      const link = /^\[([^\]]+)\]\(([^)]+)\)$/.exec(token)
      nodes.push(
        <Link key={key} href={link[2]}>
          {link[1]}
        </Link>,
      )
    }

    last = match.index + token.length
  }

  if (last < text.length) nodes.push(text.slice(last))
  return nodes
}

/* =========================================================================
 *  BẢNG — dùng Table của Ant Design
 * ========================================================================= */

/** '| a | b |' -> ['a', 'b'] */
const splitRow = (line) =>
  line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map((cell) => cell.trim())

const MdTable = ({ header, rows }) => {
  const columns = header.map((h, idx) => ({
    title: parseInline(h, `th-${idx}`),
    dataIndex: String(idx),
    key: String(idx),
  }))

  const dataSource = rows.map((row, rowIndex) => {
    const record = { key: rowIndex }
    header.forEach((_, colIndex) => {
      record[String(colIndex)] = parseInline(
        row[colIndex] ?? '',
        `td-${rowIndex}-${colIndex}`,
      )
    })
    return record
  })

  return (
    <Table
      className="md-table"
      size="small"
      bordered
      columns={columns}
      dataSource={dataSource}
      pagination={false}
      scroll={{ x: 'max-content' }}
    />
  )
}

/* =========================================================================
 *  BLOCK — duyệt từng dòng, gom thành các khối
 * ========================================================================= */

const RE_HEADING = /^(#{1,6})\s+(.*)$/
const RE_HR = /^(-{3,}|\*{3,}|_{3,})\s*$/
const RE_QUOTE = /^>\s?/
const RE_UL = /^\s*[-*]\s+/
const RE_OL = /^\s*\d+\.\s+/
const RE_TABLE_ROW = /^\s*\|/
const RE_TABLE_SEP = /^\s*\|[\s:|-]+\|\s*$/
const RE_FENCE = /^```/
// dòng bắt đầu một khối khác -> dừng gom paragraph
const RE_BLOCK_START = /^(#{1,6}\s|```|>|\s*[-*]\s|\s*\d+\.\s|\s*\|)/

/**
 * Chuyển chuỗi markdown -> mảng React node.
 * @param {string} markdown nội dung file .md
 */
export const renderMarkdown = (markdown = '') => {
  const lines = String(markdown).replace(/\r\n/g, '\n').split('\n')
  const blocks = []
  let i = 0
  let key = 0

  while (i < lines.length) {
    const line = lines[i]

    /* ---- code block ``` ---- */
    if (RE_FENCE.test(line)) {
      const buffer = []
      i++
      while (i < lines.length && !RE_FENCE.test(lines[i])) {
        buffer.push(lines[i])
        i++
      }
      i++ // bỏ dòng ``` kết thúc
      blocks.push(
        <pre className="md-code-block" key={key++}>
          <code>{buffer.join('\n')}</code>
        </pre>,
      )
      continue
    }

    /* ---- heading ---- */
    const heading = RE_HEADING.exec(line)
    if (heading) {
      const level = Math.min(heading[1].length + 1, 5)
      blocks.push(
        <Title level={level} className="md-heading" key={key++}>
          {parseInline(heading[2], `h${key}`)}
        </Title>,
      )
      i++
      continue
    }

    /* ---- đường kẻ ngang ---- */
    if (RE_HR.test(line)) {
      blocks.push(<Divider className="md-divider" key={key++} />)
      i++
      continue
    }

    /* ---- bảng ---- */
    if (RE_TABLE_ROW.test(line) && RE_TABLE_SEP.test(lines[i + 1] || '')) {
      const header = splitRow(line)
      i += 2 // bỏ dòng tiêu đề + dòng phân cách
      const rows = []
      while (i < lines.length && RE_TABLE_ROW.test(lines[i])) {
        rows.push(splitRow(lines[i]))
        i++
      }
      blocks.push(<MdTable key={key++} header={header} rows={rows} />)
      continue
    }

    /* ---- trích dẫn ---- */
    if (RE_QUOTE.test(line)) {
      const buffer = []
      while (i < lines.length && RE_QUOTE.test(lines[i])) {
        buffer.push(lines[i].replace(RE_QUOTE, ''))
        i++
      }
      blocks.push(
        <Paragraph className="md-quote" key={key++}>
          {parseInline(buffer.join(' '), `q${key}`)}
        </Paragraph>,
      )
      continue
    }

    /* ---- danh sách không thứ tự ---- */
    if (RE_UL.test(line)) {
      const items = []
      while (i < lines.length && RE_UL.test(lines[i])) {
        items.push(lines[i].replace(RE_UL, ''))
        i++
      }
      blocks.push(
        <ul className="md-list" key={key++}>
          {items.map((item, n) => (
            <li key={n}>{parseInline(item, `ul${key}-${n}`)}</li>
          ))}
        </ul>,
      )
      continue
    }

    /* ---- danh sách có thứ tự ---- */
    if (RE_OL.test(line)) {
      const items = []
      while (i < lines.length && RE_OL.test(lines[i])) {
        items.push(lines[i].replace(RE_OL, ''))
        i++
      }
      blocks.push(
        <ol className="md-list" key={key++}>
          {items.map((item, n) => (
            <li key={n}>{parseInline(item, `ol${key}-${n}`)}</li>
          ))}
        </ol>,
      )
      continue
    }

    /* ---- dòng trống ---- */
    if (!line.trim()) {
      i++
      continue
    }

    /* ---- đoạn văn: gom các dòng liên tiếp ---- */
    const buffer = []
    while (
      i < lines.length &&
      lines[i].trim() &&
      !RE_BLOCK_START.test(lines[i])
    ) {
      buffer.push(lines[i])
      i++
    }
    blocks.push(
      <Paragraph className="md-paragraph" key={key++}>
        {parseInline(buffer.join(' '), `p${key}`)}
      </Paragraph>,
    )
  }

  return blocks
}

export default renderMarkdown
